CREATE TABLE IF NOT EXISTS settings (`key` varchar(100) PRIMARY KEY, value longtext NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS users (id bigint unsigned AUTO_INCREMENT PRIMARY KEY, source_id bigint unsigned NULL UNIQUE, name varchar(190) NOT NULL, email varchar(190) NOT NULL UNIQUE, phone varchar(60) NOT NULL DEFAULT '', password_hash varchar(255) NULL, session_version int unsigned NOT NULL DEFAULT 0, role enum('customer','admin') NOT NULL DEFAULT 'customer', active tinyint NOT NULL DEFAULT 1, last_login datetime NULL, created_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS categories (id bigint unsigned AUTO_INCREMENT PRIMARY KEY, source_id bigint unsigned NULL UNIQUE, parent_id bigint unsigned NULL, name varchar(190) NOT NULL, slug varchar(190) NOT NULL UNIQUE, description text NULL, image varchar(500) NULL, sort_order int NOT NULL DEFAULT 0, active tinyint NOT NULL DEFAULT 1, FOREIGN KEY(parent_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS products (id bigint unsigned AUTO_INCREMENT PRIMARY KEY, source_id bigint unsigned NULL UNIQUE, name varchar(255) NOT NULL, slug varchar(190) NOT NULL UNIQUE, sku varchar(190) NULL UNIQUE, description longtext NULL, short_description text NULL, regular_price decimal(14,2) NOT NULL DEFAULT 0, sale_price decimal(14,2) NULL, price decimal(14,2) NOT NULL DEFAULT 0, stock decimal(14,3) NOT NULL DEFAULT 0, manage_stock tinyint NOT NULL DEFAULT 0, stock_status varchar(30) NOT NULL DEFAULT 'instock', status varchar(30) NOT NULL DEFAULT 'draft', type varchar(30) NOT NULL DEFAULT 'simple', featured tinyint NOT NULL DEFAULT 0, image varchar(500) NULL, attributes longtext NULL, tags text NULL, weight varchar(60) NULL, dimensions text NULL, seo_title varchar(255) NULL, meta_description text NULL, metadata longtext NULL, created_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(status,featured,created_at), INDEX(price), CHECK(price>=0), CHECK(stock>=0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS product_categories (product_id bigint unsigned NOT NULL, category_id bigint unsigned NOT NULL, PRIMARY KEY(product_id,category_id), FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE, FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS product_images (id bigint unsigned AUTO_INCREMENT PRIMARY KEY, product_id bigint unsigned NOT NULL, path varchar(500) NOT NULL, sort_order int NOT NULL DEFAULT 0, UNIQUE(product_id,path), FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS product_variants (id bigint unsigned AUTO_INCREMENT PRIMARY KEY, source_id bigint unsigned NULL UNIQUE, product_id bigint unsigned NOT NULL, sku varchar(190) NULL UNIQUE, attributes text NOT NULL, price decimal(14,2) NOT NULL, regular_price decimal(14,2) NOT NULL DEFAULT 0, stock decimal(14,3) NOT NULL DEFAULT 0, manage_stock tinyint NOT NULL DEFAULT 0, stock_status varchar(30) NOT NULL DEFAULT 'instock', image varchar(500) NULL, active tinyint NOT NULL DEFAULT 1, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE, CHECK(price>=0), CHECK(stock>=0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS content_categories (id bigint unsigned AUTO_INCREMENT PRIMARY KEY, source_id bigint unsigned NULL UNIQUE, name varchar(190) NOT NULL, slug varchar(190) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS content (id bigint unsigned AUTO_INCREMENT PRIMARY KEY, source_id bigint unsigned NULL UNIQUE, type enum('post','page') NOT NULL, title varchar(255) NOT NULL, slug varchar(190) NOT NULL, body longtext NULL, excerpt text NULL, image varchar(500) NULL, category_id bigint unsigned NULL, tags text NULL, author varchar(190) NULL, status varchar(30) NOT NULL DEFAULT 'draft', published_at datetime NULL, seo_title varchar(255) NULL, meta_description text NULL, UNIQUE(type,slug), INDEX(type,status,published_at), FOREIGN KEY(category_id) REFERENCES content_categories(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS banners (id bigint unsigned AUTO_INCREMENT PRIMARY KEY, source_key varchar(190) NULL UNIQUE, title varchar(255) NOT NULL, description text NULL, image varchar(500) NULL, link varchar(500) NOT NULL DEFAULT 'shop-grid.php', button_text varchar(100) NOT NULL DEFAULT 'Shop now', sort_order int NOT NULL DEFAULT 0, active tinyint NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS addresses (id bigint unsigned AUTO_INCREMENT PRIMARY KEY, source_key varchar(40) NULL, user_id bigint unsigned NOT NULL, name varchar(190) NOT NULL, phone varchar(60) NOT NULL, address text NOT NULL, city varchar(100) NOT NULL, country varchar(100) NOT NULL, created_at datetime DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,source_key), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS carts (id bigint unsigned AUTO_INCREMENT PRIMARY KEY, token char(64) NOT NULL UNIQUE, user_id bigint unsigned NULL, updated_at datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cart_items (id bigint unsigned AUTO_INCREMENT PRIMARY KEY, cart_id bigint unsigned NOT NULL, product_id bigint unsigned NOT NULL, variant_id bigint unsigned NOT NULL DEFAULT 0, quantity int unsigned NOT NULL, UNIQUE(cart_id,product_id,variant_id), FOREIGN KEY(cart_id) REFERENCES carts(id) ON DELETE CASCADE, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE, CHECK(quantity>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS wishlist_items (cart_id bigint unsigned NOT NULL, product_id bigint unsigned NOT NULL, PRIMARY KEY(cart_id,product_id), FOREIGN KEY(cart_id) REFERENCES carts(id) ON DELETE CASCADE, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS orders (id bigint unsigned AUTO_INCREMENT PRIMARY KEY, source_id bigint unsigned NULL UNIQUE, user_id bigint unsigned NULL, public_token char(64) NOT NULL UNIQUE, checkout_key char(64) NULL UNIQUE, customer_name varchar(190) NOT NULL, email varchar(190) NOT NULL, phone varchar(60) NOT NULL DEFAULT '', address text NOT NULL, city varchar(100) NOT NULL DEFAULT '', country varchar(100) NOT NULL DEFAULT '', subtotal decimal(14,2) NOT NULL, shipping decimal(14,2) NOT NULL DEFAULT 0, tax decimal(14,2) NOT NULL DEFAULT 0, total decimal(14,2) NOT NULL, currency varchar(10) NOT NULL, status varchar(30) NOT NULL DEFAULT 'pending', payment_method varchar(40) NOT NULL, payment_status varchar(30) NOT NULL DEFAULT 'unpaid', notes text NULL, created_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL, INDEX(created_at,status), INDEX(email), CHECK(total>=0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS order_items (id bigint unsigned AUTO_INCREMENT PRIMARY KEY, order_id bigint unsigned NOT NULL, product_id bigint unsigned NULL, variant_id bigint unsigned NULL, name varchar(255) NOT NULL, sku varchar(190) NULL, options text NULL, quantity int unsigned NOT NULL, unit_price decimal(14,2) NOT NULL, total decimal(14,2) NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL, FOREIGN KEY(variant_id) REFERENCES product_variants(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS order_history (id bigint unsigned AUTO_INCREMENT PRIMARY KEY, order_id bigint unsigned NOT NULL, status varchar(30) NOT NULL, note text NULL, admin_id bigint unsigned NULL, created_at datetime DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS payments (id bigint unsigned AUTO_INCREMENT PRIMARY KEY, order_id bigint unsigned NOT NULL, method varchar(40) NOT NULL, amount decimal(14,2) NOT NULL, status varchar(30) NOT NULL DEFAULT 'pending', reference varchar(190) NULL, created_at datetime DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS password_resets (id bigint unsigned AUTO_INCREMENT PRIMARY KEY, user_id bigint unsigned NOT NULL, token_hash char(64) NOT NULL UNIQUE, expires_at datetime NOT NULL, used_at datetime NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS login_attempts (id bigint unsigned AUTO_INCREMENT PRIMARY KEY, identity_hash char(64) NOT NULL, created_at datetime DEFAULT CURRENT_TIMESTAMP, INDEX(identity_hash,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS audit_logs (id bigint unsigned AUTO_INCREMENT PRIMARY KEY, admin_id bigint unsigned NULL, action varchar(100) NOT NULL, resource varchar(60) NOT NULL, resource_id bigint unsigned NULL, context text NULL, created_at datetime DEFAULT CURRENT_TIMESTAMP, INDEX(created_at), INDEX(admin_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS analytics_visitors (id char(64) PRIMARY KEY, first_seen datetime DEFAULT CURRENT_TIMESTAMP, last_seen datetime DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS analytics_sessions (id char(64) PRIMARY KEY, visitor_id char(64) NOT NULL, user_id bigint unsigned NULL, entry_page varchar(255) NOT NULL, exit_page varchar(255) NOT NULL, referrer varchar(190) NULL, source varchar(120) NULL, medium varchar(120) NULL, campaign varchar(120) NULL, device varchar(30) NULL, browser varchar(40) NULL, os varchar(40) NULL, started_at datetime DEFAULT CURRENT_TIMESTAMP, last_seen datetime DEFAULT CURRENT_TIMESTAMP, INDEX(started_at), INDEX(visitor_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS analytics_events (id bigint unsigned AUTO_INCREMENT PRIMARY KEY, session_id char(64) NOT NULL, event varchar(40) NOT NULL, page varchar(255) NULL, resource_id bigint unsigned NULL, detail varchar(190) NULL, created_at datetime DEFAULT CURRENT_TIMESTAMP, INDEX(created_at,event), INDEX(session_id), INDEX(resource_id,event)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS contact_messages (id bigint unsigned AUTO_INCREMENT PRIMARY KEY, name varchar(190) NOT NULL, email varchar(190) NOT NULL, subject varchar(255) NOT NULL, message text NOT NULL, created_at datetime DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
